def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]==0 and (r,c) not in seen:
    stack=[(r,c)]; seen.add((r,c)); comp=[]
    while stack:
     x,y=stack.pop(); comp.append((x,y))
     for p in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
      a,b=p
      if 0<=a<h and 0<=b<w and g[a][b]==0 and p not in seen: seen.add(p); stack.append(p)
    out.append(comp)
 return sorted(out,key=len,reverse=True)
